import i18next, { type i18n } from 'i18next';
import HttpBackend from 'i18next-http-backend';
import type { ReactiveController, ReactiveControllerHost } from 'lit';
import { fallbackT } from './fallback-t';
import type { TFunction } from './types';

export interface I18nConfig {
  /** Wordplex grid UUID that holds this widget's translations. */
  gridUuid: string;
  /** i18next namespace for this widget, e.g. "uploader" / "asset-picker". */
  namespace: string;
  /** Translations CDN base. Defaults to the Filerobot i18n fastly host. */
  cdnUrl?: string;
}

export interface DamI18n {
  /** Lazily create + initialise the scoped i18next instance (idempotent; switches language). */
  initI18n(locale?: string): Promise<{ i18n: i18n; isNew: boolean }>;
  /** The scoped instance, or null before init. */
  getInstance(): i18n | null;
  /** Subscribe to readiness/language changes. Returns an unsubscribe fn. */
  onChange(cb: () => void): () => void;
  /** Module-level translate bound to this instance, with fallback before init. */
  t: TFunction;
  /** Pre-init pass-through translate (no i18next). */
  fallbackT: TFunction;
  /** Lit controller that re-renders its host when translations load / language changes. */
  I18nController: new (host: ReactiveControllerHost) => ReactiveController;
}

const DEFAULT_CDN_URL = 'https://i18n-fastly.ultrafast.io';

/**
 * Create a **scoped** i18n bundle for one widget. Each widget calls this once with its own
 * grid + namespace, so widgets on the same page don't collide on a single shared instance.
 * Generalizes the identical singleton pattern from uploader + asset-picker (plan/11 F4).
 */
export function createI18n(config: I18nConfig): DamI18n {
  const cdnUrl = config.cdnUrl ?? DEFAULT_CDN_URL;
  let instance: i18n | null = null;
  const listeners = new Set<() => void>();
  const notify = (): void => {
    for (const cb of listeners) cb();
  };

  const onChange = (cb: () => void): (() => void) => {
    listeners.add(cb);
    return () => listeners.delete(cb);
  };

  async function initI18n(locale = 'en'): Promise<{ i18n: i18n; isNew: boolean }> {
    if (instance) {
      if (instance.language !== locale) {
        await instance.changeLanguage(locale);
        notify();
      }
      return { i18n: instance, isNew: false };
    }

    instance = i18next.createInstance();
    await instance.use(HttpBackend).init({
      lng: locale,
      fallbackLng: 'en',
      ns: [config.namespace],
      defaultNS: config.namespace,
      saveMissing: true,
      missingKeyNoValueFallbackToKey: false,
      interpolation: { escapeValue: false },
      backend: {
        addPath: '',
        loadPath: `${cdnUrl}/api/export/grid/f2/${config.gridUuid}?langs={{lng}}&separator=+&response_format=i18next_multi`,
        parse(data: string, languages?: string | string[]) {
          const json = JSON.parse(data) as Record<string, Record<string, Record<string, string>>>;
          const lng = Array.isArray(languages) ? languages[0] : languages;
          if (lng && json[lng]?.__without_namespace) {
            return json[lng].__without_namespace;
          }
          return json;
        },
      },
    });

    instance.on('languageChanged', notify);
    instance.on('loaded', notify);
    notify();

    return { i18n: instance, isNew: true };
  }

  const getInstance = (): i18n | null => instance;

  const t: TFunction = (key, defaultValueOrOptions?, options?) => {
    if (!instance || !instance.isInitialized) {
      return fallbackT(key, defaultValueOrOptions, options);
    }
    if (typeof defaultValueOrOptions === 'string') {
      return instance.t(key, defaultValueOrOptions, options ?? {}) as string;
    }
    return instance.t(key, defaultValueOrOptions ?? {}) as string;
  };

  class I18nController implements ReactiveController {
    private _host: ReactiveControllerHost;
    private _unsubscribe: (() => void) | null = null;

    constructor(host: ReactiveControllerHost) {
      this._host = host;
      host.addController(this);
    }

    hostConnected(): void {
      this._unsubscribe = onChange(() => this._host.requestUpdate());
    }

    hostDisconnected(): void {
      this._unsubscribe?.();
      this._unsubscribe = null;
    }
  }

  return { initI18n, getInstance, onChange, t, fallbackT, I18nController };
}
