// The single seam between the picker and wherever folders come from.
//
// Hosts that already hold a folder tree (Hub in Redux, Portals in react-query) supply
// their own implementation instead of letting the element fetch — that is the whole
// reason this is one interface rather than five props on the element.

import { createFolder, getFolders, type DamClient, type Folder } from '@scaleflex/dam-core';

export interface FolderPage {
  folders: Folder[];
  /**
   * More children exist beyond this page. The API response carries no `total`, so this
   * is inferred from `folders.length === limit` — which costs one extra empty request
   * when the count is an exact multiple, and never loses folders.
   */
  hasMore: boolean;
}

export interface ListChildrenOptions {
  offset: number;
  limit: number;
  signal?: AbortSignal;
}

export interface SearchOptions {
  /** Confine the search to this subtree. */
  rootPath: string;
  limit: number;
  /**
   * Aborted when a newer search supersedes this one. Honouring it is optional — a
   * superseded result is discarded either way by the store's sequence guard, so this only
   * saves work. `createApiFolderSource` cannot honour it: dam-core's `DamClient.get` takes
   * no signal (it owns an AbortController for its own timeout). Host-supplied sources
   * built on fetch/react-query can and should pass it through.
   */
  signal?: AbortSignal;
}

export interface FolderSource {
  listChildren(path: string, options: ListChildrenOptions): Promise<FolderPage>;
  /** Omit to disable search for this source. */
  search?(query: string, options: SearchOptions): Promise<Folder[]>;
  /** Omit to disable folder creation for this source. */
  create?(leafName: string, parentPath: string): Promise<Folder | void>;
  /** Omit to skip permission gating for this source. */
  checkPermissions?(uuid: string, required: string[]): Promise<boolean>;
}

interface FolderPermissionsResponse {
  permissions?: string[];
  source?: string;
}

/** Live source over dam-core's folders service. */
export function createApiFolderSource(client: DamClient): FolderSource {
  return {
    async listChildren(path, { offset, limit }) {
      const folders = await getFolders(client, { folderPath: path, offset, limit });
      return { folders, hasMore: folders.length === limit };
    },

    // `signal` is deliberately unused: dam-core's client accepts none. Superseded results
    // are dropped by the store, so correctness does not depend on cancelling the request.
    async search(query, { rootPath, limit }) {
      return getFolders(client, { folderPath: rootPath, q: query, recursive: 1, limit });
    },

    async create(leafName, parentPath) {
      return createFolder(client, leafName, parentPath);
    },

    async checkPermissions(uuid, required) {
      const res = await client.get<FolderPermissionsResponse>(
        `/folder/${encodeURIComponent(uuid)}/permissions`,
      );
      const granted = res?.permissions;
      if (!Array.isArray(granted)) return false;
      return required.every((p) => granted.includes(p));
    },
  };
}

/**
 * Offline source over a flat folder list — for demos, tests, and hosts that already
 * hold every folder in memory. Children are derived from `parentPath`/`path`, and
 * search is a case-insensitive substring match on the name.
 */
export function createStaticFolderSource(folders: readonly Folder[]): FolderSource {
  const parentOf = (folder: Folder): string =>
    folder.parentPath ?? (folder.path.replace(/\/[^/]*$/, '') || '/');

  return {
    async listChildren(path, { offset, limit }) {
      const children = folders
        .filter((f) => parentOf(f) === path && f.path !== path)
        .sort((a, b) => a.name.localeCompare(b.name));
      const page = children.slice(offset, offset + limit);
      return { folders: page, hasMore: offset + page.length < children.length };
    },

    async search(query, { rootPath, limit }) {
      const needle = query.toLowerCase();
      const prefix = rootPath === '/' ? '/' : `${rootPath}/`;
      return folders
        .filter((f) => f.path.startsWith(prefix) && f.name.toLowerCase().includes(needle))
        .slice(0, limit);
    },
  };
}
