// Fire a callback when a bottom sentinel scrolls into view — the headless half of
// "infinite scroll". Store-agnostic (the host owns paging); shared so light-dam and
// asset-picker stop re-implementing the same IntersectionObserver. See plan/12 D11.
import type { ReactiveController, ReactiveControllerHost } from 'lit';

export class InfiniteScrollController implements ReactiveController {
  private observer?: IntersectionObserver;
  private sentinel?: Element;
  private onLoadMore: () => void;

  constructor(host: ReactiveControllerHost, onLoadMore: () => void) {
    this.onLoadMore = onLoadMore;
    host.addController(this);
  }

  hostConnected(): void {}

  hostDisconnected(): void {
    this.disconnect();
  }

  /**
   * (Re)observe a sentinel element. `root` scopes the observer to a scroll
   * container; `rootMargin` pre-loads the next page before the sentinel is visible
   * (asset-picker uses 200px, light-dam 600px).
   */
  observe(sentinel: Element, root?: Element | null, rootMargin = '200px'): void {
    this.disconnect();
    this.sentinel = sentinel;
    this.observer = new IntersectionObserver(
      (entries) => {
        if (entries[0]?.isIntersecting) {
          this.onLoadMore();
        }
      },
      { root: root ?? null, rootMargin },
    );
    this.observer.observe(sentinel);
  }

  /** Stop observing (e.g. when the sentinel is removed on a failed load). */
  disconnect(): void {
    if (this.observer && this.sentinel) {
      this.observer.unobserve(this.sentinel);
      this.observer.disconnect();
    }
    this.observer = undefined;
    this.sentinel = undefined;
  }
}
