import { css, unsafeCSS } from 'lit';

/**
 * Canonical `--sfx-*` theme tokens, shared across all DAM widgets. oklch color space
 * (adopted from asset-picker) so opacity-based tones derive naturally. Widget-specific
 * subsystems (asset-picker's panel/sidebar/chart, etc.) stay app-local and may alias onto
 * these. See plan/11 (F4).
 */
export const themeTokensText = `:host {
  /* Base */
  --sfx-background: oklch(1 0 0);
  --sfx-foreground: oklch(0.37 0.022 248.413);
  --sfx-card: oklch(1 0 0);
  --sfx-card-foreground: oklch(0.37 0.022 248.413);
  --sfx-popover: oklch(1 0 0);
  --sfx-popover-foreground: oklch(0.37 0.022 248.413);

  /* Primary */
  --sfx-primary: oklch(0.578 0.198 268.129);
  --sfx-primary-foreground: oklch(1 0 0);
  --sfx-primary-10: oklch(0.578 0.198 268.129 / 0.1);
  --sfx-primary-20: oklch(0.578 0.198 268.129 / 0.2);

  /* Secondary / Muted / Accent */
  --sfx-secondary: oklch(98.16% 0.002 247.84);
  --sfx-secondary-foreground: oklch(53.03% 0.039 249.89);
  --sfx-muted: oklch(0.974 0.006 239.819);
  --sfx-muted-foreground: oklch(0.685 0.033 249.82);
  --sfx-accent: oklch(0.578 0.198 268.129 / 0.07);
  --sfx-accent-foreground: oklch(0.578 0.198 268.129);

  /* Status */
  --sfx-success: oklch(0.637 0.17 151.295);
  --sfx-success-foreground: oklch(0.429 0.107 154.754);
  --sfx-success-10: oklch(0.978 0.025 163.82);
  --sfx-destructive: oklch(0.577 0.215 27.325);
  --sfx-destructive-foreground: oklch(0.472 0.173 26.157);
  --sfx-destructive-10: oklch(0.967 0.016 17.438);
  --sfx-info: oklch(0.632 0.161 245.564);
  --sfx-info-foreground: oklch(0.391 0.091 241.289);
  --sfx-info-10: oklch(0.978 0.025 248.61);
  --sfx-warning: oklch(0.734 0.157 69.419);
  --sfx-warning-foreground: oklch(0.456 0.095 58.822);
  --sfx-warning-10: oklch(0.978 0.025 86.868);

  /* Border / Input / Ring / Shadow / Selection */
  --sfx-border: oklch(92.86% 0.009 247.92);
  --sfx-input: oklch(0.871 0.016 241.798);
  --sfx-ring: oklch(0.578 0.198 268.129 / 0.7);
  --sfx-shadow: oklch(26.18% 0.024 256.43 / 0.1);
  --sfx-selection-bg: oklch(0.578 0.198 268.129 / 0.08);

  /* Typography */
  --sfx-font-family: system-ui, -apple-system, sans-serif;
  --sfx-font-size-sm: 0.875rem;
  --sfx-font-size-base: 1rem;

  /* Radius */
  --sfx-radius: 8px;
  --sfx-radius-sm: 6px;
  --sfx-radius-lg: 12px;
}`;

/** The canonical token block as a Lit `css` fragment — include in a component's `static styles`. */
export const themeTokens = css`
  ${unsafeCSS(themeTokensText)}
`;

/**
 * Back-compat alias fragments. During migration (Phase 4) a widget can include the matching
 * fragment so its existing `var(--ap-*)` / `var(--sfx-up-*)` / `var(--sfx-ld-*)` references
 * resolve onto the shared `--sfx-*` tokens without a sweeping find-replace. Widget-only
 * tokens (panel/sidebar/chart, derived shades) stay defined in the widget.
 */
export const aliasAssetPicker = css`
  :host {
    --ap-background: var(--sfx-background);
    --ap-foreground: var(--sfx-foreground);
    --ap-primary: var(--sfx-primary);
    --ap-primary-foreground: var(--sfx-primary-foreground);
    --ap-primary-10: var(--sfx-primary-10);
    --ap-primary-20: var(--sfx-primary-20);
    --ap-muted: var(--sfx-muted);
    --ap-muted-foreground: var(--sfx-muted-foreground);
    --ap-accent: var(--sfx-accent);
    --ap-accent-foreground: var(--sfx-accent-foreground);
    --ap-border: var(--sfx-border);
    --ap-input: var(--sfx-input);
    --ap-ring: var(--sfx-ring);
    --ap-success: var(--sfx-success);
    --ap-destructive: var(--sfx-destructive);
    --ap-info: var(--sfx-info);
    --ap-warning: var(--sfx-warning);
    --ap-radius: var(--sfx-radius);
    --ap-radius-sm: var(--sfx-radius-sm);
    --ap-radius-lg: var(--sfx-radius-lg);
  }
`;

export const aliasUploader = css`
  :host {
    --sfx-up-primary: var(--sfx-primary);
    --sfx-up-text: var(--sfx-foreground);
    --sfx-up-text-secondary: var(--sfx-secondary-foreground);
    --sfx-up-text-muted: var(--sfx-muted-foreground);
    --sfx-up-bg: var(--sfx-background);
    --sfx-up-border: var(--sfx-border);
    --sfx-up-ring: var(--sfx-ring);
    --sfx-up-success: var(--sfx-success);
    --sfx-up-error: var(--sfx-destructive);
    --sfx-up-warning: var(--sfx-warning);
  }
`;

export const aliasLightDam = css`
  :host {
    --sfx-ld-accent: var(--sfx-primary);
    --sfx-ld-fg: var(--sfx-foreground);
    --sfx-ld-muted: var(--sfx-muted-foreground);
    --sfx-ld-border: var(--sfx-border);
    --sfx-ld-bg: var(--sfx-background);
    --sfx-ld-danger: var(--sfx-destructive);
    --sfx-ld-radius: var(--sfx-radius);
  }
`;
