/**
 * Brand-color application for the shared `--sfx-*` theme. Parses a hex color and derives the
 * primary/accent/ring/selection tokens in oklch so opacity-based tones come out naturally.
 * Generalized from asset-picker's `applyBrandColor` (plan/11 F4) to the `--sfx-*` prefix.
 */

function hexToSrgb(hex: string): [number, number, number] {
  const h = hex.replace('#', '');
  const full = h.length === 3 ? h[0] + h[0] + h[1] + h[1] + h[2] + h[2] : h;
  const r = parseInt(full.slice(0, 2), 16) / 255;
  const g = parseInt(full.slice(2, 4), 16) / 255;
  const b = parseInt(full.slice(4, 6), 16) / 255;
  return [r, g, b];
}

function linearize(c: number): number {
  return c <= 0.04045 ? c / 12.92 : Math.pow((c + 0.055) / 1.055, 2.4);
}

function srgbToOklch(r: number, g: number, b: number): [number, number, number] {
  const lr = linearize(r);
  const lg = linearize(g);
  const lb = linearize(b);

  const l_ = 0.4122214708 * lr + 0.5363325363 * lg + 0.0514459929 * lb;
  const m_ = 0.2119034982 * lr + 0.6806995451 * lg + 0.1073969566 * lb;
  const s_ = 0.0883024619 * lr + 0.2817188376 * lg + 0.6299787005 * lb;

  const l1 = Math.cbrt(l_);
  const m1 = Math.cbrt(m_);
  const s1 = Math.cbrt(s_);

  const L = 0.2104542553 * l1 + 0.793617785 * m1 - 0.0040720468 * s1;
  const a = 1.9779984951 * l1 - 2.428592205 * m1 + 0.4505937099 * s1;
  const bk = 0.0259040371 * l1 + 0.7827717662 * m1 - 0.808675766 * s1;

  const C = Math.sqrt(a * a + bk * bk);
  let h = Math.atan2(bk, a) * (180 / Math.PI);
  if (h < 0) h += 360;

  return [L, C, h];
}

/** Light colors need dark foreground text. */
function needsDarkForeground(L: number): boolean {
  return L > 0.7;
}

/**
 * Apply a brand color (hex) to an element by overriding the primary/accent `--sfx-*` tokens.
 * Pass an empty string to clear the overrides.
 */
export function applyBrandColor(el: HTMLElement, hex: string): void {
  const props = [
    '--sfx-primary',
    '--sfx-primary-foreground',
    '--sfx-primary-10',
    '--sfx-primary-20',
    '--sfx-accent',
    '--sfx-accent-foreground',
    '--sfx-ring',
    '--sfx-selection-bg',
  ];

  if (!hex) {
    for (const prop of props) el.style.removeProperty(prop);
    return;
  }

  const [r, g, b] = hexToSrgb(hex);
  const [L, C, h] = srgbToOklch(r, g, b);

  const lch = `${L.toFixed(3)} ${C.toFixed(3)} ${h.toFixed(1)}`;
  const base = `oklch(${lch})`;
  const fg = needsDarkForeground(L) ? '#000' : '#fff';

  el.style.setProperty('--sfx-primary', base);
  el.style.setProperty('--sfx-primary-foreground', fg);
  el.style.setProperty('--sfx-primary-10', `oklch(${lch} / 0.1)`);
  el.style.setProperty('--sfx-primary-20', `oklch(${lch} / 0.2)`);
  el.style.setProperty('--sfx-accent', `oklch(${lch} / 0.07)`);
  el.style.setProperty('--sfx-accent-foreground', base);
  el.style.setProperty('--sfx-ring', `oklch(${lch} / 0.7)`);
  el.style.setProperty('--sfx-selection-bg', `oklch(${lch} / 0.08)`);
}

/** Set arbitrary `--sfx-*` token overrides on an element. */
export function applyTheme(el: HTMLElement, tokens: Record<string, string>): void {
  for (const [key, value] of Object.entries(tokens)) {
    const prop = key.startsWith('--') ? key : `--sfx-${key}`;
    el.style.setProperty(prop, value);
  }
}
