// @scaleflex/dam-core — file variations + container presets service.
// Endpoints verified against js-admin-react-filerobot-v5 / portals-fe:
//   GET /v5/file/{uuid}/variants  → { variants: RawVariation[] }
//   GET /v5/settings              → container config incl. cloudimg presets
import type { DamClient } from './dam-client';
import type { Asset } from '../types/asset.types';
import type { Variation, Preset } from '../types/variation.types';
import type {
  GetVariationsResponse,
  GetSettingsResponse,
  RawVariation,
  RawPreset,
} from '../types/api.types';
import { assembleVariations } from '../helpers/variations';

/** List a file's raw variations (custom + background-removed renditions). */
export async function getFileVariations(client: DamClient, uuid: string): Promise<RawVariation[]> {
  const res = await client.get<GetVariationsResponse>(
    `/file/${encodeURIComponent(uuid)}/variants`,
  );
  return res?.variants ?? [];
}

/** Normalize the various preset shapes (`string` | `{ name, desc }`) into `Preset[]`. */
export function normalizePresets(raw: RawPreset[] | undefined): Preset[] {
  if (!Array.isArray(raw)) return [];
  return raw
    .map((p): Preset | null =>
      typeof p === 'string'
        ? { name: p }
        : p && typeof p.name === 'string'
          ? { name: p.name, desc: p.desc }
          : null,
    )
    .filter((p): p is Preset => p !== null);
}

/**
 * Fetch the container's resolution presets from `/settings`. The presets array
 * lives under the container's cloudimg config; its exact nesting varies by
 * deployment, so we probe the known locations defensively (verify against a live
 * container — Q-AP presets).
 */
export async function getPresets(client: DamClient): Promise<Preset[]> {
  const res = await client.get<GetSettingsResponse>('/settings');
  const raw =
    res?.presets ?? res?.cloudimg?.presets ?? res?.settings?.cloudimg?.presets ?? undefined;
  return normalizePresets(raw);
}

/**
 * Convenience: fetch a file's variants + the container presets and assemble the
 * full ordered `Variation[]` (Original + custom + background-removed + presets).
 * Hosts that already hold variants/presets can call `assembleVariations` directly
 * instead (the fetch-or-inject contract).
 */
export async function loadVariations(client: DamClient, asset: Asset): Promise<Variation[]> {
  const [variants, presets] = await Promise.all([
    getFileVariations(client, asset.uuid),
    getPresets(client),
  ]);
  return assembleVariations({ asset, variants, presets });
}
